# owner: platform
"""Weekly timesheet lines built from a list of shifts."""

from hourglass.models import Shift

def _check(shift):
    if not shift.worker.strip():
        raise ValueError("shift has a blank worker")

def _tally(shifts):
    totals = {}
    for shift in shifts:
        _check(shift)
        count, mins = totals.get(shift.worker, (0, 0))
        mins += shift.span.minutes
        totals[shift.worker] = (count + 1, mins)
    return totals

def _line(name, stats):
    count, mins = stats
    return f"{name}: {count} shifts, {mins / 60:.1f} hours"

def _busy(item):
    return (-item[1][1], item[0])

# ---
def timesheet_lines(shifts: list[Shift]) -> list[str]:
    """One line per worker, most total hours first."""
    if not shifts:
        raise ValueError("no shifts to total")
    rows = sorted(_tally(shifts).items(), key=_busy)
    return [_line(name, stats) for name, stats in rows]

